<?= view('layout/header') ?><h1>User Accounts</h1><p><a class="btn" href="<?= site_url('users/new') ?>">New User</a></p><table><thead><tr><th>Avatar</th><th>Username</th><th>Full name</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><td><img class="avatar" alt="User avatar" src="<?= $row['avatar'] ? base_url('uploads/avatars/'.rawurlencode($row['avatar'])) : base_url('images/avatar-placeholder.svg') ?>"></td><td><?= esc($row['username']) ?></td><td><?= esc($row['full_name']) ?></td><td><a href="<?= site_url('users/'.$row['id'].'/edit') ?>">Edit</a></td></tr><?php endforeach; ?></tbody></table><?= view('layout/footer') ?>
